static void eth_disable (void)
{
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) &= ~(1<<5);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_SOURCE2) &= ~((1<<6)|(1<<7)|(1<<8)); //set eth rm|mtx|mrx clock source to xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG1) |= (1<<4)|(1<<5)|(1<<6);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<15);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<28);
}

static void eth_enable(void)
{
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_SOURCE2) |= (1<<6)|(1<<7)|(1<<8); //set eth rm|mtx|mrx clock source to pll
}

static void dvb_disable(void)
{
	/* Disable DVB related clock */
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<21)|(1<<22)|(1<<23)|(1<<27)|(1<<30);
	/* Disable ABS related clock */
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<24)|(1<<25)|(1<<26);
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG1) |= (1<<12)|(1<<13)|(1<<14)|(1<<15)|(1<<16);
}

static void dvb_enable(void)
{
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE1) |= 1 << 26; // ADC clock source from xtal to PLL
#ifdef ABS_CHANNEL
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE1) |= 1 << 11; // ABS ADC clock source from xtal to ADC clock
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_DVB_SELECT)    |= 1 << 0;
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_SYSTEM_MUX_CONFIG) |= (1 << 3) | (1 << 5); //set i2c4 connect to ABS

	/* Disable DVB related clock in ABS mode */
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<21)|(1<<22)|(1<<23)|(1<<27)|(1<<30);
#else
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE1) |= 1 << 31; // ts_base clock source from xtal to pll
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_GLB) |= 1 << 2; // IQADC to DVB clock source
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE1) |= 1 << 28; // DVB ADC clock source from xtal to ADC clock or PLL
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_DVB_SELECT)    &= ~(1 << 0);

#ifdef DVB_CHANNEL_S2
	/* Disable DVB demod_l clk */
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<23);
#else /* DVB_CHANNEL_C */
	/* Disable DVB fec clk and demod_h clk */
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<21)|(1<<22);
#endif
	/* Disable ABS related clock in DVB mode */
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<24)|(1<<25)|(1<<26);
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG1) |= (1<<12)|(1<<13)|(1<<14)|(1<<15)|(1<<16);
#endif

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  0x3;
}

void gx_setup_pll_full_controller(void)
{
	int i;
#ifdef DVB_CHANNEL_S2
#ifdef CONFIG_24M_XTAL
	unsigned int dvb_clk = 1536000000;
#else /* 27MHz XTAL */
	unsigned int dvb_clk = 1539000000;
#endif
#elif defined(DVB_CHANNEL_C)
	unsigned int dvb_clk = 1080000000;
#elif defined(ABS_CHANNEL)
#ifdef CONFIG_24M_XTAL
	unsigned int dvb_clk = 1536000000;
#else /* 27MHz XTAL */
	unsigned int dvb_clk = 1161000000;
#endif
#endif
	unsigned int ts_clock_source_cfg = 0;
	unsigned int hdmi_clock_source_cfg = 0;

#if defined(DVB_CHANNEL_S2) || defined(DVB_CHANNEL_C) || defined(ABS_CHANNEL)
	PLL_Config(CONFIG_BASE_MMU + CONFIG_DVB_PLL_CONFIG, dvb_clk);    // PLL_DVB
	while ((*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_PLL_CONFIG_IN) & 0xF) != 0xF); // wait pll dvb lock
#endif

	// DTO config
	for (i = 0; i < sizeof(dto_table_full)/sizeof(struct dto_param); i++) {
		DTO_Config(&dto_table_full[i], 1);
	}
	for (i = 0; i < sizeof(dto_sec_table_full)/sizeof(struct dto_param); i++) {
		DTO_Sec_Config(&dto_sec_table_full[i], 1);
	}

	// DIV config
	for (i = 0; i < sizeof(div_table_full)/sizeof(struct div_param); i++)
		DIV_Config(&div_table_full[i], 1);
	for (i = 0; i < sizeof(div_sec_table_full)/sizeof(struct div_param); i++)
		DIV_Sec_Config(&div_sec_table_full[i], 1);

#ifdef VDEC_AND_ADSP_CLK_FROM_DDR
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_GLB) |= 3 << 0;
#endif
	/* HDMI TMDS clk */
	hdmi_clock_source_cfg |= 1 << 25;
	/* HDMI pre clk */
	hdmi_clock_source_cfg |= 1 << 26;
	*(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= hdmi_clock_source_cfg;

	eth_enable();
#if defined(DVB_CHANNEL_S2) || defined(DVB_CHANNEL_C) || defined(ABS_CHANNEL)
	dvb_enable();
#else
	dvb_disable();
#endif

	USB_Init();

	// select VDAC clock source 0: VPU VDAC clock 1: SVPU VDAC clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE1) |= (1<<14);

	/************** TS clock ****************/
	ts_clock_source_cfg |= (1<<10);//ts serial channel1
	ts_clock_source_cfg |= (1<<11);//ts parallel channel1
	ts_clock_source_cfg |= (1<<12);//ts parallel channel2
	ts_clock_source_cfg |= (1<<13);//ts parallel channel3
	ts_clock_source_cfg |= (1<<14);//ts serial   channel2
	ts_clock_source_cfg |= (1<<27);//ts serial   channel3
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= ts_clock_source_cfg;

#if 0
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= (1<<15);//ts serial channel1 clk edge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= (1<<16);//ts parallel channel1 clk edge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= (1<<17);//ts parallel channel2 clk edge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= (1<<18);//ts parallel channel3 clk edge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= (1<<19);//ts serial channel2 clk edge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) |= (1<<28);//ts serial channel3 clk edge
#endif

#ifdef ENABLE_SECURE_ALIGN
	// usb
	*(volatile unsigned int*)(USB_CONFIG_BASE + CONFIG_USB3_CONFIG) |= 1;
	// demux
	*(volatile unsigned int*)(REG_BASE_DEMUX + 0x47F0) |= 0x3;
	// gp
	*(volatile unsigned int*)(REG_BASE_GP) |= (1<<5);
	// audio_or
	*(volatile unsigned int*)(REG_BASE_AUDIO_OR + 0x1EC) |= (0x7);
	// ga
	*(volatile unsigned int*)(REG_BASE_GA + 0x34) |= 1;
	// m2m
	*(volatile unsigned int*)(REG_BASE_M2M + 0x2400) |= 1;
#endif

	/* close firewall */
	*(volatile unsigned int *)(REG_BASE_FIREWALL) = 0x0; // disable enable all instance & hide default filter
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x4) = CMDLINE_DRAM_SIZE;
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x310) = 0xffffffff;
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x314) = 0xffffffff;
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x8) = 0x01; // Upload reg config
}

void gx_power_reduction(void)
{
        /* close vdec clock */
        *(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE1) &= ~(1<<16);
        *(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= 1<<15;
	/* close bist clock */
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG1) |= (1<<7);
	/* close gc300 clock */
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG0) |= (1<<20);

#ifdef CONFIG_CLOCK_ETH_DISABLE
	eth_disable();
#endif
#ifndef CONFIG_ENABLE_NANDFLASH
#ifdef CONFIG_CLOCK_ETH_DISABLE /* 因为 eth 和 NFC 控制器共用了一个 NOC 总线, 当关闭 NFC 时钟会导致 eth 没法使用 */
	/* close AHB NFC clock */
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<13);
#endif
#endif

#ifdef CONFIG_CLOCK_GP_DISABLE
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_SEC) &= ~((1<<4)|(1<<5));
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<4)|(1<<5);
#endif
#ifdef CONFIG_CLOCK_GSE_DISABLE
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_SEC) &= ~(1<<3);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<3);
#endif
#ifdef CONFIG_CLOCK_PIDFILTER_DISABLE
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_SEC) &= ~(1<<2);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<2);
#endif
#ifdef CONFIG_CLOCK_SDIO_DISABLE
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE2) &= ~(1<<21);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG1) |= (1<<9)|(1<<10)|(1<<11);
#endif
#ifdef CONFIG_CLOCK_SMARTCARD_DISABLE
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_SEC) &= ~(1<<16);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<19);
#endif
#ifdef CONFIG_CLOCK_SCPU_DISABLE
	/* close scpu clock */
	//*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_SOURCE_SEC) &= ~(1<<7);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_GATE_REG_SEC) |= (1<<7);
#endif
}
